let stream = null;
        let currentFacingMode = 'environment'; // Default to rear camera
        const videoElement = document.getElementById('camera-feed');
        const containerElement = document.getElementById('scanner-container');
        const btnToggleCam = document.getElementById('btn-toggle-cam');
        const btnSwitchCam = document.getElementById('btn-switch-cam');
        const placeholder = document.getElementById('camera-placeholder');
        const statusText = document.getElementById('sensor-status-text');
        const statusDot = document.getElementById('sensor-dot');

        async function startCamera(facingMode = 'environment') {
            try {
                if (stream) {
                    stream.getTracks().forEach(track => track.stop());
                }

                const constraints = {
                    video: {
                        facingMode: facingMode,
                        // Optimize for higher frame rate if possible to better capture fast banding,
                        // though standard rolling shutter will capture it regardless.
                        frameRate: { ideal: 60, min: 30 }
                    }
                };

                stream = await navigator.mediaDevices.getUserMedia(constraints);
                videoElement.srcObject = stream;

                // Adjust mirror effect
                if (facingMode === 'user') {
                    videoElement.style.transform = 'scaleX(-1)';
                } else {
                    videoElement.style.transform = 'scaleX(1)';
                }

                currentFacingMode = facingMode;

                // Update UI
                placeholder.style.display = 'none';
                containerElement.classList.add('scanning-active');
                btnToggleCam.innerHTML = `<svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 10a1 1 0 011-1h4a1 1 0 011 1v4a1 1 0 01-1 1h-4a1 1 0 01-1-1v-4z"></path></svg> Stop Scanning`;
                btnToggleCam.classList.replace('btn-primary', 'btn-danger');
                btnSwitchCam.disabled = false;

                // Update Status Indicator
                statusText.innerText = "Optical Sensor Active";
                statusDot.className = "w-2.5 h-2.5 bg-green-500 rounded-full animate-pulse";

                showToast("Camera Active. Point at screen.");

            } catch (err) {
                console.error("Error accessing camera:", err);
                showToast("Error: Camera permission denied or device not found.");
                stopCamera();
            }
        }

        function stopCamera() {
            if (stream) {
                stream.getTracks().forEach(track => track.stop());
                stream = null;
            }
            videoElement.srcObject = null;

            // Update UI
            placeholder.style.display = 'flex';
            containerElement.classList.remove('scanning-active');
            btnToggleCam.innerHTML = `<svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M14.752 11.168l-3.197-2.132A1 1 0 0010 9.87v4.263a1 1 0 001.555.832l3.197-2.132a1 1 0 000-1.664z"></path><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg> Start Camera Scan`;
            btnToggleCam.classList.replace('btn-danger', 'btn-primary');
            btnSwitchCam.disabled = true;

            // Update Status Indicator
            statusText.innerText = "Camera Standby";
            statusDot.className = "w-2.5 h-2.5 bg-slate-300 rounded-full";
        }

        function toggleCamera() {
            if (stream) {
                stopCamera();
            } else {
                startCamera(currentFacingMode);
            }
        }

        function switchCamera() {
            if (!stream) return;
            const newMode = currentFacingMode === 'environment' ? 'user' : 'environment';
            startCamera(newMode);
            showToast(`Switched to ${newMode === 'user' ? 'Front' : 'Rear'} Camera`);
        }

        // --- Utility: Toast Notification ---
        function showToast(msg) {
            const toast = document.createElement('div');
            toast.className = "fixed top-24 left-1/2 -translate-x-1/2 bg-slate-800 text-white px-8 py-3 rounded-full shadow-2xl z-[100] animate-fadeIn font-black text-xs uppercase tracking-widest border border-blue-500";
            toast.innerText = msg;
            document.body.appendChild(toast);
            setTimeout(() => {
                toast.style.opacity = '0';
                toast.style.transition = 'opacity 0.5s ease';
                setTimeout(() => toast.remove(), 500);
            }, 3000);
        }

        // Ensure cleanup on page unload
        window.addEventListener('beforeunload', stopCamera);
